/* FitFirst V2 — Pilot analytics and the Baseline Log.
   Analytics keeps the real page's order (verdict card → stat grid → basket and revenue charts → top recommended and slow stock tables)
   but uses the corrected metric definitions and adds the measured clearance effect, the funnel and rejection reasons.
   Baseline Log keeps the real daily ledger form and the kill-threshold card, and makes the threshold lockable. */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES, CH = FF.chart;
  const A = { days: 21 };
  const perDay = (days, fn) => { const o = []; for (let d = days - 1; d >= 0; d--) { const a = new Date(Date.now() - d * FF.DAY).setHours(0, 0, 0, 0); o.push({ l: FF.fmtDate(a), v: fn(a, a + FF.DAY), a }); } return o; };

  FF.page('analytics', { title: 'Pilot analytics', icon: 'chart', roles: R.MGR, render: () => {
    const db = FF.db, m = FF.metrics(A.days), p = db.settings.pilot, enough = m.sessions >= 100 && m.baseN >= 60;
    const lift = m.baseBasket ? (m.basket / m.baseBasket - 1) * 100 : null, conv = m.sessions ? (m.recBuy / m.sessions) * 100 : null, usage = m.usage == null ? null : m.usage * 100;
    const targets = [['Average bill vs before FitFirst', lift, p.basketLift, lift == null ? 'No baseline bills yet' : `${FF.inr(m.basket)} now vs ${FF.inr(m.baseBasket)} before`, true], ['Bought a recommended piece', conv, p.recConv, `${m.recBuy} of ${m.sessions} consultations`], ['Shoppers who used FitFirst', usage, p.usage, usage == null ? 'Log footfall in the Baseline Log' : `${m.sessions} of ${m.footfall} people through the door`]];
    const pass = targets.every((t) => t[1] != null && t[1] >= t[2]), V = !enough ? ['wait', 'clock', 'Collecting data', `A fair verdict needs at least 100 consultations and 60 baseline bills (now ${m.sessions} and ${m.baseN}). Early signs are below.`] : pass ? ['pass', 'check', 'Pilot is meeting every target', 'All three numbers agreed before go-live are being met.'] : ['fail', 'alert', 'Pilot is below target', 'At least one agreed number is not being met yet. The targets do not move.'];
    const basket = perDay(Math.min(30, A.days + 7), (a, b) => { const S = db.sales.filter((s) => s.at >= a && s.at < b); return S.length ? FF.sum(S, (s) => s.total) / S.length : 0; }).map((d) => Object.assign(d, { c: d.a >= p.start ? CH.ink : CH.soft, t: `${d.l}: average bill ${FF.inr(d.v)}${d.a >= p.start ? ' · FitFirst live' : ' · baseline'}` }));
    const rev = perDay(A.days, (a, b) => FF.sum(db.sales.filter((s) => s.at >= a && s.at < b), (s) => s.total)), revFF = perDay(A.days, (a, b) => FF.sum(db.sales.filter((s) => s.at >= a && s.at < b && s.visit), (s) => s.total));
    const shown = {}; m.V.forEach((v) => v.picks.forEach((pk) => { const x = (shown[pk.pid] = shown[pk.pid] || { pid: pk.pid, n: 0, sold: 0, rank: 0 }); x.n++; x.rank += pk.rank; if (pk.state === 'bought') x.sold++; }));
    const top = Object.values(shown).sort((a, b) => b.n - a.n).slice(0, 6), slow = db.products.filter((x) => x.status === 'LIVE' && FF.ageBand(x) !== 'fresh').sort((a, b) => FF.ageDays(b) - FF.ageDays(a)).slice(0, 6), fmax = Math.max(1, m.funnel[0][1]);
    return `<div class="ph1"><div><div class="eyebrow">Analytics · ${U.demo('Demo numbers')}</div><h1 class="mt8">Pilot analytics</h1><p>Is FitFirst earning its place in the shop? Every figure comes from a bill, a scan or a staff tap. Tap ⓘ on any number to see how it is worked out.</p></div><div class="row wrap">${U.seg('a-days', [[7, '7 days'], [21, 'Since go-live'], [30, '30 days']], A.days)}<button class="btn" data-act="a-export">${FF.icon('download')} Export</button></div></div>
      <div class="verdict ${V[0]} reveal"><div class="vi ${V[0] === 'pass' ? 'ok' : V[0] === 'fail' ? 'bad' : 'brass'}">${FF.icon(V[1])}</div><div class="grow"><h2 style="font-size:21px">${V[2]}</h2><p class="small mt4">${V[3]}</p>
        <div class="mt12">${targets.map(([l, v, t, sub, plus]) => `<div class="target"><div><b class="inkc">${l}</b> <span class="small muted">· ${sub}</span></div><div class="num"><b class="${v == null ? 'muted' : v >= t ? 'ok' : 'bad'}">${v == null ? '—' : (plus && v >= 0 ? '+' : '') + v.toFixed(1) + '%'}</b> <span class="small muted">target ${plus ? '+' : ''}${t}%</span></div><div class="bar2"><i style="width:${v == null ? 0 : FF.clamp((v / (t * 1.6)) * 100, 2, 100)}%;background:${v != null && v >= t ? 'var(--sage)' : 'var(--ink)'}"></i><b style="left:${100 / 1.6}%" title="Target"></b></div></div>`).join('')}</div><p class="tiny muted mt8">Targets locked ${p.locked ? 'on ' + FF.fmtDate(p.lockedAt) : '— not yet locked'} · week ${Math.min(p.weeks, Math.floor((Date.now() - p.start) / FF.DAY / 7) + 1)} of ${p.weeks}. <a class="link" href="#/baseline">Baseline Log</a></p></div></div>
      <div class="grid g3 mt16">${U.kpi('Aged stock cleared', FF.inrK(m.agedCleared), `${FF.inrK(m.agedAttr)} through a FitFirst pick`, { info: 'Sale lines that were past their fresh window on the day they sold, at the price actually charged.' })}${U.kpi('Extra old stock sold', m.lift == null ? '<span style="font-size:20px">Not enough data</span>' : (m.lift >= 0 ? '+' : '') + Math.round(m.lift * 100) + '%', m.lift == null ? `control group has ${m.nHold} visits; 20 needed` : `${(m.rb * 100).toFixed(1)}% vs ${(m.rh * 100).toFixed(1)}% in the control group`, { info: 'About 1 in 10 shoppers get picks with no old-stock nudge. Comparing the two groups measures the effect instead of claiming it.' })}${U.kpi('Consultations', m.sessions, `${m.abandoned} left midway`)}
        ${U.kpi('Time to purchase', Math.round(m.mins) + ' min', 'first answer to bill')}${U.kpi('Pieces tried per sale', m.tried.toFixed(1), 'fewer = less staff time')}${U.kpi('Revenue through FitFirst', FF.inrK(FF.sum(m.S.filter((s) => s.visit), (s) => s.total)), `of ${FF.inrK(m.revenue)} total`, { info: 'Bills linked to a visit by a scanned QR, the code on the bill, or a sale recorded from the visit. Likely-but-unproven matches are never counted here.' })}</div>
      <div class="grid g2 stack sec"><div class="card"><div class="row between"><h3>Average bill by day</h3><span class="row gap16 tiny muted"><span class="row gap6"><i class="dot" style="color:var(--ink)"></i>FitFirst live</span><span class="row gap6"><i class="dot" style="color:var(--line-2)"></i>Baseline</span></span></div><div class="mt12">${CH.bars(basket, { fmt: FF.inrK, label: 'Average bill by day' })}</div></div>
        <div class="card"><h3>Daily revenue</h3><div class="mt12">${CH.line([{ name: 'All bills', c: CH.ink, pts: rev.map((x) => x.v) }, { name: 'Through FitFirst', c: CH.brass, pts: revFF.map((x) => x.v), dash: true }], rev.map((x) => x.l), { fmt: FF.inrK, label: 'Daily revenue' })}</div></div></div>
      <div class="grid g3 sec"><div class="card"><h3>From shown to bought</h3><p class="small muted">Pieces across all consultations</p><div class="funnel mt16">${m.funnel.map(([l, v]) => `<div><span>${l}</span><i style="width:${(v / fmax) * 100}%"></i><span class="num right"><b class="inkc">${v}</b> <span class="muted">${FF.pct(v, fmax)}</span></span></div>`).join('')}</div></div>
        <div class="card"><h3>Why pieces were rejected</h3><p class="small muted">One tap by staff after a fitting</p><div class="mt16">${m.reasons.length ? CH.hbar(m.reasons.slice(0, 6)) : '<p class="small muted">No rejections recorded.</p>'}</div></div>
        <div class="card"><h3>How sales were linked</h3><p class="small muted">Only proven links count</p><dl class="kv mt16" style="grid-template-columns:1fr max-content">${[['QR_SCAN', 'QR scanned at the counter'], ['HANDOFF_CODE', 'Code typed on the bill'], ['STAFF_LINKED', 'Recorded from the session']].map(([a, l]) => `<dt>${l}</dt><dd class="num right">${m.S.filter((s) => s.attribution === a).length}</dd>`).join('')}</dl><hr><p class="small">Shopper rating <b class="inkc">${(() => { const r = m.V.filter((v) => v.rating); return r.length ? (FF.sum(r, (v) => v.rating) / r.length).toFixed(1) + ' / 5' : '—'; })()}</b></p></div></div>
      <div class="grid g2 stack sec"><div><div class="sh"><h2>Most recommended</h2></div>${U.table('topr', [{ k: 'p', l: 'Product', html: (x) => { const pr = FF.prod(x.pid); return `<div class="row"><div class="thumb">${FF.garment(pr)}</div><b class="inkc">${esc(pr.name)}</b></div>`; } }, { k: 'n', l: 'Times shown', r: 1, html: (x) => x.n }, { k: 's', l: 'Shown / sold', r: 1, html: (x) => `${x.n} / ${x.sold}` }, { k: 'r', l: 'Avg rank', r: 1, html: (x) => (x.rank / x.n).toFixed(1) }], top, { per: 6 })}</div>
        <div><div class="sh"><h2>Slow stock</h2><a class="link small" href="#/clearance">Clearance controls</a></div>${U.table('slow', [{ k: 'p', l: 'Product', html: (x) => `<div class="row"><div class="thumb">${FF.garment(x)}</div><b class="inkc">${esc(x.name)}</b></div>` }, { k: 'd', l: 'Days in', html: (x) => U.ageBadge(x) }, { k: 'st', l: 'Stock', r: 1, html: (x) => FF.stockTotal(x) }, { k: 'sh', l: 'Shown · 7d', r: 1, html: (x) => x.imp7 }], slow, { per: 6 })}</div></div>`; } });
  FF.act('a-days', (d) => { A.days = +d.v; FF.render(); });
  FF.act('a-export', () => { const m = FF.metrics(A.days); FF.download('fitfirst-pilot-summary.csv', FF.csv([['Metric', 'Value'], ['Period (days)', A.days], ['Consultations', m.sessions], ['Bought a recommended piece', m.recBuy], ['Aged stock cleared (₹)', Math.round(m.agedCleared)], ['Control-group visits', m.nHold], ['Average bill with FitFirst (₹)', Math.round(m.basket)], ['Average bill baseline (₹)', Math.round(m.baseBasket)], ['Note', 'Synthetic demo data']])); });

  /* ---------- Baseline Log ---------- */
  const B = { tx: '', rev: '' };
  FF.page('baseline', { title: 'Baseline Log', icon: 'book', roles: R.MGR, render: () => {
    const db = FF.db, p = db.settings.pilot, owner = FF.me().role === 'OWNER', L = db.ledger || [], base = L.filter((x) => !x.kiosk), live = L.filter((x) => x.kiosk);
    const avg = (rows) => { const tx = FF.sum(rows, (r) => r.tx); return tx ? FF.sum(rows, (r) => r.rev) / tx : 0; };
    const live$ = B.tx > 0 && B.rev > 0 ? FF.inr(B.rev / B.tx) : null;
    return `<div class="ph1"><div><div class="eyebrow">Pilot</div><h1 class="mt8">Baseline Log</h1><p>The daily sales ledger. Days before FitFirst went live are the “before”; days after are compared against them. Where the billing software has history, these rows fill themselves.</p></div></div>
      <div class="grid g4">${U.kpi('Baseline days', base.length, 'aim for 14 or more')}${U.kpi('Average bill · before', FF.inr(avg(base)), 'total revenue ÷ total bills')}${U.kpi('Days with FitFirst', live.length, 'since ' + FF.fmtDate(p.start))}${U.kpi('Average bill · with FitFirst', FF.inr(avg(live)), base.length ? ((avg(live) / avg(base) - 1) * 100 >= 0 ? '+' : '') + ((avg(live) / avg(base) - 1) * 100).toFixed(1) + '% vs before' : '')}</div>
      <div class="split sec"><div class="card"><h2>Add a day</h2><p class="small muted mt4">One entry per day. Saving a date that already exists updates it.</p>
        <form data-submit="bl-save" class="grid g2 mt16">${U.field('Date', `<input name="date" type="date" required max="${FF.day(Date.now())}" value="${FF.day(Date.now())}">`)}${U.field('People through the door', '<input name="footfall" type="number" min="0" max="5000" placeholder="Optional — needed for usage">')}${U.field('Bills', `<input name="tx" type="number" min="0" max="2000" required data-change="bl-live" data-k="tx" value="${B.tx}" data-msg="How many bills were made?">`)}${U.field('Revenue (₹)', `<input name="rev" type="number" min="0" required data-change="bl-live" data-k="rev" value="${B.rev}" data-msg="Total sales for the day">`)}
          ${U.field('Average pieces per bill', '<input name="units" type="number" min="0" max="20" step="0.1" placeholder="e.g. 1.4">')}<div class="field"><label>Average bill</label><div class="kpi" style="padding:8px 12px" id="bl-avg"><span class="serif inkc" style="font-size:22px">${live$ || '—'}</span></div></div>
          <div class="field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes" maxlength="120" placeholder="e.g. Wedding season weekend, more footfall"></textarea></div>
          <label class="check" style="grid-column:1/-1"><input type="checkbox" name="kiosk" checked> <span>FitFirst was in use this day</span></label><div><button class="btn btn-p">Save day</button></div></form></div>
      <div class="col gap16"><div class="card"><div class="row between"><h2>Pass marks</h2>${p.locked ? U.badge('Locked', 'ok') : U.badge('Not locked', 'warn')}</div><p class="small muted mt4">Agreed with the shop before go-live. If they are not met, we accept FitFirst is not working here.</p>
        <dl class="kv mt16" style="grid-template-columns:1fr max-content">${[['Average bill above before', 'basketLift', '+'], ['Consultations that buy a pick', 'recConv', ''], ['Shoppers who use FitFirst', 'usage', '']].map(([l, k, s]) => `<dt>${l}</dt><dd class="num">${p.locked ? `<b>${s}${p[k]}%</b>` : `<input type="number" min="1" max="100" value="${p[k]}" data-change="pl-t" data-lazy data-k="${k}" style="width:70px;min-height:30px;padding:2px 8px" aria-label="${l}"> %`}</dd>`).join('')}<dt>Control group</dt><dd class="num"><b>${db.settings.holdout}%</b></dd></dl>
        ${p.locked ? `<p class="note n-ok mt16 small">Locked on ${FF.fmtDate(p.lockedAt)}. Nobody can change these during the pilot — that is the point.</p>` : owner ? `<button class="btn btn-p mt16" data-act="pl-lock">${FF.icon('lock')} Lock for the pilot</button>` : `<p class="note small mt16">Only the owner can lock these.</p>`}</div>
        <div class="note n-info small"><b>How to use this log</b><br>Log every day, including slow ones. Untick “FitFirst was in use” for days before go-live. Aim for at least 14 baseline days. Revenue is the day’s gross sales in rupees.</div></div></div>
      <div class="sec"><div class="sh"><h2>Ledger</h2><button class="btn btn-s" data-act="bl-export">${FF.icon('download')} Export</button></div>${U.table('ledger', [{ k: 'd', l: 'Date', sort: (r) => r.date, html: (r) => `<span class="mono">${r.date}</span>` }, { k: 'k', l: 'Period', html: (r) => (r.kiosk ? U.badge('FitFirst live', 'ok') : U.badge('Baseline')) }, { k: 'f', l: 'Footfall', r: 1, html: (r) => r.footfall || '—' }, { k: 't', l: 'Bills', r: 1, sort: (r) => r.tx, html: (r) => r.tx }, { k: 'rv', l: 'Revenue', r: 1, sort: (r) => r.rev, html: (r) => FF.inr(r.rev) }, { k: 'a', l: 'Avg bill', r: 1, html: (r) => (r.tx ? FF.inr(r.rev / r.tx) : '—') }, { k: 'n', l: 'Notes', html: (r) => `<span class="small muted">${esc(r.notes || '')}</span>` }], L, { sort: 'd', dir: -1, per: 10 })}<p class="tiny muted mt8">${U.demo()} Rows marked as imported come from the demo bills.</p></div>`; } });
  FF.onChange('bl-live', (v, el) => { B[el.dataset.k] = v === '' ? '' : Number(v); const box = $('#bl-avg span'); if (box) box.textContent = B.tx > 0 && B.rev > 0 ? FF.inr(B.rev / B.tx) : '—'; });
  FF.act('bl-save', (f) => { const db = FF.db, L = db.ledger, ex = L.find((r) => r.date === f.date), row = { date: f.date, tx: f.tx, rev: f.rev, units: f.units || 0, notes: f.notes, kiosk: f.kiosk, footfall: f.footfall || (ex && ex.footfall) || 0, by: FF.me().name };
    if (ex) Object.assign(ex, row); else L.push(row); L.sort((a, b) => (a.date < b.date ? -1 : 1));
    const bl = db.baseline.find((b) => b.date === f.date); if (bl) { if (f.footfall) bl.footfall = f.footfall; } else if (f.footfall) db.baseline.push({ date: f.date, kiosk: f.kiosk, footfall: f.footfall, note: f.notes });
    FF.audit(ex ? 'Updated ledger day' : 'Logged ledger day', f.date, FF.inr(f.rev)); B.tx = ''; B.rev = ''; FF.save(); FF.render(); FF.toast(ex ? 'Updated ' + f.date : 'Saved ' + f.date, 'ok'); });
  FF.act('bl-export', () => FF.download('baseline-ledger.csv', FF.csv([['Date', 'Period', 'Footfall', 'Bills', 'Revenue', 'Avg pieces', 'Notes']].concat(FF.db.ledger.map((r) => [r.date, r.kiosk ? 'FitFirst' : 'Baseline', r.footfall, r.tx, r.rev, r.units, r.notes])))));
})();
